mapper.select:
SELECT ar.id, ar.audit_no AS auditNo, ar.audit_type AS auditType, ar.business_id AS businessId, ar.title, ar.content, ar.current_status AS currentStatus, ar.priority, ar.applicant_id AS applicantId, ar.submit_time AS submitTime, ar.current_admin_id AS currentAdminId, u.name AS applicantName, u.avatar AS applicantAvatar, p.title AS reportedContent, p.user_id AS reportedUserId, pu.name AS reportedUserName, a.name AS currentAdminName FROM audit_record ar LEFT JOIN user_info u ON ar.applicant_id = u.id LEFT JOIN forum_post p ON ar.business_id = p.id LEFT JOIN user_info pu ON p.user_id = pu.id LEFT JOIN admin_info a ON ar.current_admin_id = a.id WHERE ar.audit_type = 5 AND ar.is_deleted = 0
AND ar.current_status = #{query.status}
AND ar.priority = #{query.priority}
AND (ar.audit_no LIKE CONCAT('%', #{query.keyword}, '%') OR ar.title LIKE CONCAT('%', #{query.keyword}, '%') OR ar.content LIKE CONCAT('%', #{query.keyword}, '%'))
AND ar.submit_time >= #{query.startTime}
AND ar.submit_time <= #{query.endTime}
ORDER BY ar.priority DESC, ar.current_status ASC, ar.submit_time DESC

SELECT ar.id, ar.audit_no AS auditNo, ar.audit_type AS auditType, ar.business_id AS businessId, ar.title, ar.content, ar.current_status AS currentStatus, ar.priority, ar.applicant_id AS applicantId, ar.submit_time AS submitTime, ar.current_admin_id AS currentAdminId, u.name AS applicantName, u.avatar AS applicantAvatar, r.content AS reportedContent, r.user_id AS reportedUserId, ru.name AS reportedUserName, a.name AS currentAdminName FROM audit_record ar LEFT JOIN user_info u ON ar.applicant_id = u.id LEFT JOIN post_reply r ON ar.business_id = r.id LEFT JOIN user_info ru ON r.user_id = ru.id LEFT JOIN admin_info a ON ar.current_admin_id = a.id WHERE ar.audit_type = 4 AND ar.is_deleted = 0
AND ar.current_status = #{query.status}
AND ar.priority = #{query.priority}
AND (ar.audit_no LIKE CONCAT('%', #{query.keyword}, '%') OR ar.title LIKE CONCAT('%', #{query.keyword}, '%') OR ar.content LIKE CONCAT('%', #{query.keyword}, '%'))
AND ar.submit_time >= #{query.startTime}
AND ar.submit_time <= #{query.endTime}
ORDER BY ar.priority DESC, ar.current_status ASC, ar.submit_time DESC
